const fs=require('fs');
const http=require('http');
const server=http.createServer((req,res)=>{const file='/tmp/opencode/'+req.url.slice(1);if(!fs.existsSync(file)){res.writeHead(404);return res.end()}res.setHeader('Access-Control-Allow-Origin','*');res.setHeader('Content-Type','image/png');fs.createReadStream(file).pipe(res)}).listen(9230,'127.0.0.1');
const chrome=spawn('chromium',['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9224','--user-data-dir=/tmp/opencode/chrome-convert','about:blank']);
const wait=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{let ws;try{let tabs;for(let i=0;i<30;i++){try{tabs=await fetch('http://127.0.0.1:9224/json').then(r=>r.json());if(tabs.length)break}catch{}await wait(250)}ws=new WebSocket(tabs[0].webSocketDebuggerUrl);await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});let id=0,pending=new Map();ws.onmessage=e=>{let m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){let q=pending.get(m.id);pending.delete(m.id);m.error?q.reject(m.error):q.resolve(m.result)}};function call(method,params={}){return new Promise((resolve,reject)=>{let n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}))})}async function conv(src,dst){await call('Page.navigate',{url:'http://127.0.0.1:9230/'+src.split('/').pop()});await wait(300);let r=await call('Runtime.evaluate',{expression:`(()=>{let i=document.querySelector('img');let c=document.createElement('canvas');c.width=i.naturalWidth;c.height=i.naturalHeight;c.getContext('2d').drawImage(i,0,0);return c.toDataURL('image/jpeg',.78)})()`,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.text);fs.writeFileSync(dst,Buffer.from(r.result.value.split(',')[1],'base64'));console.log(dst,fs.statSync(dst).size,'bytes')}await call('Runtime.enable');await call('Page.enable');await conv('/tmp/opencode/final-desktop.png','/tmp/opencode/final-desktop.jpg');await conv('/tmp/opencode/final-mobile.png','/tmp/opencode/final-mobile.jpg')}catch(e){console.error(e);process.exitCode=1}finally{ws?.close();chrome.kill();server.close()}})();

